package com.bautruc.ecommerce.order.application;
import java.time.Instant;import java.util.*;import com.bautruc.ecommerce.common.exception.*;import com.bautruc.ecommerce.common.time.BusinessClock;import com.bautruc.ecommerce.order.domain.*;import com.bautruc.ecommerce.order.infrastructure.*;import com.bautruc.ecommerce.payment.application.PaymentQueryPort;import com.bautruc.ecommerce.payment.domain.PaymentStatus;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class OrderCommandService{
 private final OrderJpaRepository orders;private final OrderItemJpaRepository items;private final OrderCodeGenerator codes;private final BusinessClock clock;private final PaymentQueryPort payments;
 public OrderCommandService(OrderJpaRepository o,OrderItemJpaRepository i,OrderCodeGenerator c,BusinessClock b,PaymentQueryPort p){orders=o;items=i;codes=c;clock=b;payments=p;}
 @Transactional public CreatedOrder create(CreateOrderCommand c,Instant now){if(c.lines()==null||c.lines().isEmpty())throw new BusinessException("CART_EMPTY","Cart is empty.");long total=0;for(OrderLineCommand l:c.lines())total=Math.addExact(total,Math.multiplyExact(l.sellingPrice(),l.quantity()));Long id=orders.nextId();Order order=orders.save(new Order(id,codes.generate(id,now,clock.businessZone()),c.userId(),c.receiverName(),c.phone(),c.email(),c.address(),c.note(),total,now));List<OrderItem> saved=items.saveAll(c.lines().stream().map(l->new OrderItem(id,l.productId(),l.productNameVi(),l.productNameEn(),l.basePrice(),l.sellingPrice(),l.quantity())).toList());return new CreatedOrder(order,List.copyOf(saved));}
 @Transactional public Order transition(Long id,OrderStatus target){Order o=orders.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException(OrderErrorCodes.ORDER_NOT_FOUND,"Order not found."));if(payments.statusForOrderForUpdate(id)!=PaymentStatus.PAID)throw new BusinessException(OrderErrorCodes.ORDER_NOT_PAID,"Order payment is not paid.",HttpStatus.CONFLICT);Instant now=clock.now();try{if(target==OrderStatus.CONFIRMED)o.confirm(now);else if(target==OrderStatus.COMPLETED)o.complete(now);else throw new IllegalStateException();}catch(IllegalStateException e){throw new BusinessException(OrderErrorCodes.ORDER_INVALID_TRANSITION,"Invalid order transition.",HttpStatus.CONFLICT);}return o;}
}
